<?php
/**
 * Standalone UI/UX patch installer generated from the submitted Laravel project.
 * Only resources/views/... files are touched. No database, routes, controllers,
 * models, .env, public uploads, or authorization logic is changed.
 *
 * Usage: php install_saas_ui_ux.php --check
 *        php install_saas_ui_ux.php --apply
 *        php install_saas_ui_ux.php --force  (overwrite conflicts, with backups)
 *        php install_saas_ui_ux.php --restore=YYYYmmdd_HHMMSS
 */
declare(strict_types=1);

$project = __DIR__;
if (!is_file($project . '/artisan') || !is_dir($project . '/resources/views')) {
    fwrite(STDERR, "ERROR: Save this file in the Laravel project root (beside artisan).\n");
    exit(1);
}
$raw = gzuncompress(base64_decode('', true));
$data = json_decode((string) $raw, true);
if (!is_array($data)) {
    fwrite(STDERR, "ERROR: Invalid installer payload.\n");
    exit(1);
}
$mode = $argv[1] ?? '--check';
$force = in_array('--force', $argv, true);
$normalizedHash = static fn(string $text): string => hash('sha256', str_replace("\r\n", "\n", $text));
$assertRel = static function(string $path): void {
    if (!str_starts_with($path, 'resources/views/') || !str_ends_with($path, '.blade.php') || str_contains($path, '..') || str_contains($path, "\\")) {
        throw new RuntimeException('Unsafe destination path: ' . $path);
    }
};

if (str_starts_with($mode, '--restore=')) {
    $name = substr($mode, strlen('--restore='));
    if (!preg_match('/^[0-9]{8}_[0-9]{6}(?:_[0-9]+)?$/', $name)) {
        fwrite(STDERR, "ERROR: Invalid restore ID.\n"); exit(1);
    }
    $backupRoot = $project . '/storage/app/ui_ux_backups/' . $name;
    $manifest = json_decode((string) @file_get_contents($backupRoot . '/manifest.json'), true);
    if (!is_array($manifest) || !isset($manifest['files'])) {
        fwrite(STDERR, "ERROR: Backup manifest was not found.\n"); exit(1);
    }
    foreach ($manifest['files'] as $relative => $info) {
        $assertRel($relative);
        $dest = $project . '/' . $relative;
        if (!is_file($dest) || $normalizedHash((string)file_get_contents($dest)) !== ($info['applied_sha'] ?? '')) {
            if (!$force) {
                fwrite(STDERR, "CONFLICT: File changed since update: $relative\nRun with --force to overwrite local edits.\n");
                exit(2);
            }
        }
    }
    foreach ($manifest['files'] as $relative => $info) {
        $dest = $project . '/' . $relative;
        if (!empty($info['created'])) { @unlink($dest); echo "REMOVE $relative\n"; continue; }
        $source = $backupRoot . '/' . $relative;
        if (!is_file($source)) throw new RuntimeException('Missing backup: ' . $relative);
        if (@file_put_contents($dest, file_get_contents($source), LOCK_EX) === false) throw new RuntimeException('Cannot restore: ' . $relative);
        echo "RESTORE $relative\n";
    }
    echo "Restored files. Run php artisan view:clear and php artisan optimize:clear.\n";
    exit(0);
}

if (!in_array($mode, ['--check', '--apply', '--force'], true)) {
    fwrite(STDERR, "Usage: php install_saas_ui_ux.php --check | --apply | --force | --restore=BACKUP_ID\n"); exit(1);
}
$changes=[];
$conflicts=[];
$already=0;
foreach ($data as $relative => $entry) {
    $assertRel($relative);
    $dest = $project . '/' . $relative;
    $current = is_file($dest) ? $normalizedHash((string) file_get_contents($dest)) : null;
    if ($current === $entry['after']) { $already++; continue; }
    $status = $current === null ? 'CREATE' : ($entry['before'] !== null && $current === $entry['before'] ? 'UPDATE' : 'CONFLICT');
    if ($status === 'CONFLICT') $conflicts[]=$relative;
    $changes[$relative]=$status;
    echo str_pad($status, 9) . ' ' . $relative . "\n";
}
echo "Summary: " . count($changes) . " changes, $already already installed, " . count($conflicts) . " conflicts.\n";
if ($mode === '--check') {
    echo "Preview only — no files or database were modified.\n";
    if ($conflicts) echo "Conflicts must be reviewed; --force backs them up before replacement.\n";
    exit(0);
}
if ($conflicts && !$force) {
    fwrite(STDERR, "STOPPED: Existing files differ from the supplied project. Nothing changed.\nUse --force only after reviewing --check; all replaced files are backed up.\n");
    exit(2);
}
if (!$changes) { echo "UI patch is already installed.\n"; exit(0); }
$backupName = date('Ymd_His') . '_' . getmypid();
$backupRoot = $project . '/storage/app/ui_ux_backups/' . $backupName;
if (!is_dir($backupRoot) && !@mkdir($backupRoot, 0775, true) && !is_dir($backupRoot)) {
    fwrite(STDERR, "ERROR: Cannot create backup directory: $backupRoot\n"); exit(1);
}
$manifest = ['created_at'=>date(DATE_ATOM),'files'=>[]];
foreach ($changes as $relative => $status) {
    $dest = $project . '/' . $relative;
    $wasExisting = is_file($dest);
    if ($wasExisting) {
        $backup = $backupRoot . '/' . $relative;
        if (!is_dir(dirname($backup)) && !@mkdir(dirname($backup),0775,true) && !is_dir(dirname($backup))) throw new RuntimeException('Cannot create backup dir: ' . dirname($backup));
        if (!@copy($dest,$backup)) throw new RuntimeException('Backup failed: ' . $relative);
    }
    $manifest['files'][$relative] = ['created'=>!$wasExisting,'applied_sha'=>$data[$relative]['after']];
}
if (@file_put_contents($backupRoot . '/manifest.json',json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX) === false) {
    throw new RuntimeException('Backup manifest could not be written.');
}
$written=0;
foreach ($changes as $relative => $status) {
    $dest = $project . '/' . $relative;
    if (!is_dir(dirname($dest)) && !@mkdir(dirname($dest), 0775, true) && !is_dir(dirname($dest))) throw new RuntimeException('Cannot create directory: ' . dirname($dest));
    $content = base64_decode($data[$relative]['content'],true);
    if ($content === false || $normalizedHash($content) !== $data[$relative]['after']) throw new RuntimeException('Payload checksum mismatch: '.$relative);
    if (@file_put_contents($dest, $content, LOCK_EX) === false) throw new RuntimeException('Write failed: ' . $relative);
    $written++;
}
echo "Installed $written files. Backup ID: $backupName\n";
echo "Restore: php install_saas_ui_ux.php --restore=$backupName\n";
echo "Next: php artisan view:clear && php artisan optimize:clear\n";
